"""Generates TypeScript constant files for shared/src/generated/ straight from the specifications,
so the code can never drift from the documents:
  permissions.ts  <- docs/permissions.md          (every permission key + which roles hold it)
  roles.ts        <- docs/canon.md                (the seven system roles)
  modules.ts      <- docs/canon.md                (34 modules: code, name, release phase)
  errorCodes.ts   <- docs/prd/92-appendix-error-codes.md
Run after any change to those documents:  python gen_shared_constants.py
"""
import json
import re
from pathlib import Path

DOCS = Path(__file__).resolve().parent.parent
OUT = DOCS.parent / "shared" / "src" / "generated"
HEADER = "// Generated by docs/build/gen_shared_constants.py from {src}. Do not edit by hand.\n\n"
CELL = {"yes": "yes", "no": "no", "own": "own", "campus": "campus", "view": "view"}


def cells(line: str) -> list[str]:
    return [c.strip().strip("`").strip() for c in line.strip().strip("|").split("|")]


def permissions() -> tuple[list[dict], set[str]]:
    text = (DOCS / "permissions.md").read_text(encoding="utf-8")
    rows, seen = [], set()
    for line in text.splitlines():
        if not line.strip().startswith("|"):
            continue
        c = cells(line)
        if len(c) < 9 or not re.fullmatch(r"[a-z_]+\.[a-z_]+", c[0]):
            continue
        scopes = [CELL.get(x.lower()) for x in c[2:9]]
        if any(s is None for s in scopes) or c[0] in seen:
            continue
        seen.add(c[0])
        rows.append({"key": c[0], "meaning": c[1], "scopes": scopes})
    return rows, {r["key"].split(".")[0] for r in rows}


def roles() -> list[dict]:
    text = (DOCS / "canon.md").read_text(encoding="utf-8")
    out = []
    for line in text.splitlines():
        c = cells(line) if line.strip().startswith("|") else []
        if len(c) == 4 and re.fullmatch(r"[A-Z_]+", c[0]):
            out.append({"key": c[0], "label": c[1], "who": c[2], "scope": c[3]})
    return out


def modules() -> list[dict]:
    text = (DOCS / "canon.md").read_text(encoding="utf-8")
    out = []
    for line in text.splitlines():
        if not line.strip().startswith("|"):
            continue
        c = cells(line)
        if len(c) != 8:
            continue
        for a, b, code, phase in (c[0:4], c[4:8]):
            if a.isdigit() and re.fullmatch(r"[A-Z]{2,4}", code) and phase.isdigit():
                out.append({"n": int(a), "name": b, "code": code, "phase": int(phase)})
    return sorted(out, key=lambda m: m["n"])


def error_codes() -> list[dict]:
    text = (DOCS / "prd" / "92-appendix-error-codes.md").read_text(encoding="utf-8")
    out, seen = [], set()
    for line in text.splitlines():
        if not line.strip().startswith("|"):
            continue
        c = cells(line)
        if len(c) < 3 or not re.fullmatch(r"[A-Z][A-Z0-9_]{3,}", c[0]) or c[0] in seen:
            continue
        status = next((int(x) for x in c[1:3] if re.fullmatch(r"[1-5]\d\d", x)), None)
        if status is None:
            continue
        seen.add(c[0])
        message = next((x for x in c[1:] if len(x) > 12 and not x.isdigit()), "")
        out.append({"code": c[0], "status": status, "message": message})
    return out


def ts_union(name: str, values: list[str]) -> str:
    return f"export type {name} =\n" + "\n".join(f"  | '{v}'" for v in values) + ";\n\n"


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    perms, prefixes = permissions()
    role_rows = roles()
    role_keys = [r["key"] for r in role_rows]
    body = HEADER.format(src="docs/permissions.md")
    body += ts_union("PermissionKey", [p["key"] for p in perms])
    body += "export type PermissionScope = 'yes' | 'no' | 'own' | 'campus' | 'view';\n\n"
    body += "/** Every permission with what it means and the scope each system role gets. */\n"
    body += "export const PERMISSIONS = " + json.dumps(
        {p["key"]: {"meaning": p["meaning"], "scopes": dict(zip(role_keys, p["scopes"]))} for p in perms},
        indent=2) + " as const;\n\n"
    body += f"export const PERMISSION_KEYS = Object.keys(PERMISSIONS) as PermissionKey[];\n"
    body += "export const PERMISSION_PREFIXES = " + json.dumps(sorted(prefixes)) + " as const;\n\n"
    body += """/** The scope a role has for a permission: 'no' means the route is refused. */
export function scopeFor(role: SystemRole, key: PermissionKey): PermissionScope {
  return (PERMISSIONS[key]?.scopes as Record<string, PermissionScope>)[role] ?? 'no';
}

/** True when the role may call the route at all; ownership is still checked in the service. */
export function roleHasPermission(role: SystemRole, key: PermissionKey): boolean {
  return scopeFor(role, key) !== 'no';
}
"""
    body = body.replace("import type { SystemRole }", "")
    (OUT / "permissions.ts").write_text("import type { SystemRole } from './roles';\n\n" + body, encoding="utf-8", newline="\n")

    r = HEADER.format(src="docs/canon.md")
    r += ts_union("SystemRole", role_keys)
    r += "export const SYSTEM_ROLES = " + json.dumps(
        {x["key"]: {"label": x["label"], "who": x["who"], "dataScope": x["scope"]} for x in role_rows}, indent=2) + " as const;\n\n"
    r += "export const SYSTEM_ROLE_KEYS = Object.keys(SYSTEM_ROLES) as SystemRole[];\n"
    (OUT / "roles.ts").write_text(r, encoding="utf-8", newline="\n")

    mods = modules()
    m = HEADER.format(src="docs/canon.md")
    m += ts_union("ModuleCode", [x["code"] for x in mods])
    m += "export const MODULES = " + json.dumps(
        {x["code"]: {"number": x["n"], "name": x["name"], "phase": x["phase"]} for x in mods}, indent=2) + " as const;\n\n"
    m += "export const MODULE_CODES = Object.keys(MODULES) as ModuleCode[];\n"
    m += "/** Phase 1 is the 60-day MVP, phase 2 is V1.0, phase 3 V1.5, phase 4 V2.0. */\n"
    m += "export const PHASE_1_MODULES = MODULE_CODES.filter((c) => MODULES[c].phase === 1);\n"
    (OUT / "modules.ts").write_text(m, encoding="utf-8", newline="\n")

    errs = error_codes()
    e = HEADER.format(src="docs/prd/92-appendix-error-codes.md")
    e += ts_union("ErrorCode", [x["code"] for x in errs])
    e += "export const ERROR_CODES = " + json.dumps(
        {x["code"]: {"status": x["status"], "message": x["message"]} for x in errs}, indent=2) + " as const;\n\n"
    e += "export const ERROR_CODE_KEYS = Object.keys(ERROR_CODES) as ErrorCode[];\n"
    e += "export function httpStatusFor(code: ErrorCode): number {\n  return ERROR_CODES[code]?.status ?? 500;\n}\n"
    (OUT / "errorCodes.ts").write_text(e, encoding="utf-8", newline="\n")

    (OUT / "index.ts").write_text(
        HEADER.format(src="the specification documents") +
        "export * from './roles';\nexport * from './permissions';\nexport * from './modules';\nexport * from './errorCodes';\n",
        encoding="utf-8", newline="\n")
    print(f"generated: {len(perms)} permissions, {len(role_rows)} roles, {len(mods)} modules, {len(errs)} error codes -> shared/src/generated/")


if __name__ == "__main__":
    main()
